def compare_bc(bc1, bc2):
    """
    Compare two dictionaries and return a list of keys that are different.
    """
    differences = []
    list1 = bc[bc1].split('%')
    list2 = bc[bc2].split('%')
    for i in range(len(list1)):
        if list1[i] != list2[i]:
            subList1 = list1[i].split(',')
            subList2 = list2[i].split(',')
            length = max(len(subList1), len(subList2))
            temp = []
            temp.append(subList1[0])
            for j in range(1, length):
                if j >= len(subList1):
                    temp.append((bc2, subList2[j]))
                elif j >= len(subList2):
                    temp.append((bc1, subList1[j]))
                elif j < len(subList1) and j < len(subList2):
                    # Compare elements at the same index
                    if subList1[j] != subList2[j]:
                        temp.append((subList1[j], subList2[j]))
            
            differences.append(temp)
    return differences

def print_bc(differences):
    """
    Print the differences between two dictionaries.
    """
    for diff in differences:
        print(diff, '\n')
        

